) AS s (
  allergies,
  company_id,
  created_at,
  date_of_birth,
  department,
  division_id,
  division_name,
  email,
  gender,
  hire_date,
  id,
  leader_id,
  name,
  person_id,
  phone,
  photo_url,
  rfid,
  role,
  season,
  session,
  sort_order,
  specialty_sports,
  staff_type,
  status,
  tshirt_size,
  updated_at
)
LEFT JOIN public.divisions d
  ON d.company_id = '0d0b7f4f-327e-4497-83ff-3aa501ffc295'::uuid
 AND trim(d.name) = trim(s.division_name)
WHERE NOT EXISTS (
  SELECT 1 FROM public.staff c
  WHERE c.company_id = '0d0b7f4f-327e-4497-83ff-3aa501ffc295'::uuid
    AND trim(c.person_id) = trim(s.person_id)
);

-- 2) Update existing rows to match Lovable (same VALUES source)
UPDATE public.staff AS st
SET
  allergies = NULLIF(trim(s.allergies), ''),
  date_of_birth = NULLIF(trim(s.date_of_birth), '')::date,
  department = NULLIF(trim(s.department), ''),
  division_id = d.id,
  email = NULLIF(trim(s.email), ''),
  gender = NULLIF(trim(s.gender), ''),
  hire_date = NULLIF(trim(s.hire_date), '')::date,
  leader_id = CASE WHEN trim(COALESCE(s.leader_id, '')) ~ '^[0-9a-fA-F-]{36}$' THEN trim(s.leader_id)::uuid ELSE NULL END,
  name = trim(s.name),
  phone = NULLIF(trim(s.phone), ''),
  photo_url = NULLIF(trim(s.photo_url), ''),
  rfid = NULLIF(trim(s.rfid), ''),
  role = trim(s.role),
  season = NULLIF(trim(s.season), ''),
  session = NULLIF(trim(s.session), ''),
  sort_order = NULLIF(trim(s.sort_order), '')::integer,
  specialty_sports = CASE
          WHEN trim(COALESCE(s.specialty_sports, '')) IN ('', '[]') THEN '{}'::text[]
          ELSE ARRAY(SELECT jsonb_array_elements_text(trim(s.specialty_sports)::jsonb))
        END,
